     1→//! Training Load calculations (ATL/CTL/ACWR).
     2→//!
     3→//! Implements the Performance Management Chart (PMC) model:
     4→//! - ATL (Acute Training Load): 7-day exponentially weighted moving average
     5→//! - CTL (Chronic Training Load): 42-day exponentially weighted moving average
     6→//! - TSB (Training Stress Balance): CTL - ATL
     7→//! - ACWR (Acute:Chronic Workload Ratio): ATL / CTL
     8→
     9→use chrono::NaiveDate;
    10→use serde::{Deserialize, Serialize};
    11→
    12→/// Daily training load values.
    13→#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize)]
    14→pub struct DailyLoad {
    15→    /// Total TSS for the day.
    16→    pub tss: f32,
    17→    /// Acute Training Load (7-day EWMA).
    18→    pub atl: f32,
    19→    /// Chronic Training Load (42-day EWMA).
    20→    pub ctl: f32,
    21→    /// Training Stress Balance (CTL - ATL).
    22→    pub tsb: f32,
    23→}
    24→
    25→/// ACWR status thresholds.
    26→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    27→pub enum AcwrStatus {
    28→    /// ACWR < 0.8: Undertrained (detraining risk).
    29→    Undertrained,
    30→    /// ACWR 0.8 - 1.3: Optimal training zone.
    31→    Optimal,
    32→    /// ACWR 1.3 - 1.5: Caution zone.
    33→    Caution,
    34→    /// ACWR > 1.5: High injury risk.
    35→    HighRisk,
    36→}
    37→
    38→/// Acute:Chronic Workload Ratio result.
    39→#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
    40→pub struct Acwr {
    41→    /// The ratio value.
    42→    pub ratio: f32,
    43→    /// Status classification.
    44→    pub status: AcwrStatus,
    45→}
    46→
    47→/// Training load calculator.
    48→pub struct TrainingLoadCalculator {
    49→    /// ATL decay constant (default: 7 days).
    50→    atl_days: f32,
    51→    /// CTL decay constant (default: 42 days).
    52→    ctl_days: f32,
    53→}
    54→
    55→impl TrainingLoadCalculator {
    56→    /// Create with default constants (7/42 day).
    57→    pub fn new() -> Self {
    58→        Self {
    59→            atl_days: 7.0,
    60→            ctl_days: 42.0,
    61→        }
    62→    }
    63→
    64→    /// Create with custom decay constants.
    65→    pub fn with_constants(atl_days: f32, ctl_days: f32) -> Self {
    66→        Self { atl_days, ctl_days }
    67→    }
    68→
    69→    /// Calculate training load for a date given previous day's values and today's TSS.
    70→    pub fn calculate_day(&self, prev: DailyLoad, today_tss: f32) -> DailyLoad {
    71→        // EWMA formula: new = old × (1 - k) + value × k
    72→        // where k = 2 / (N + 1)
    73→        let atl_k = 2.0 / (self.atl_days + 1.0);
    74→        let ctl_k = 2.0 / (self.ctl_days + 1.0);
    75→
    76→        let new_atl = prev.atl * (1.0 - atl_k) + today_tss * atl_k;
    77→        let new_ctl = prev.ctl * (1.0 - ctl_k) + today_tss * ctl_k;
    78→        let new_tsb = new_ctl - new_atl;
    79→
    80→        DailyLoad {
    81→            tss: today_tss,
    82→            atl: new_atl,
    83→            ctl: new_ctl,
    84→            tsb: new_tsb,
    85→        }
    86→    }
    87→
    88→    /// Calculate full history from daily TSS values.
    89→    pub fn calculate_history(&self, daily_tss: &[(NaiveDate, f32)]) -> Vec<(NaiveDate, DailyLoad)> {
    90→        if daily_tss.is_empty() {
    91→            return Vec::new();
    92→        }
    93→
    94→        let mut results = Vec::with_capacity(daily_tss.len());
    95→        let mut prev = DailyLoad::default();
    96→
    97→        for (date, tss) in daily_tss {
    98→            let load = self.calculate_day(prev, *tss);
    99→            results.push((*date, load));
   100→            prev = load;
   101→        }
   102→
   103→        results
   104→    }
   105→
   106→    /// Calculate ACWR from current ATL/CTL.
   107→    pub fn acwr(&self, atl: f32, ctl: f32) -> Acwr {
   108→        let ratio = if ctl > 0.0 { atl / ctl } else { 0.0 };
   109→
   110→        let status = if ratio < 0.8 {
   111→            AcwrStatus::Undertrained
   112→        } else if ratio <= 1.3 {
   113→            AcwrStatus::Optimal
   114→        } else if ratio <= 1.5 {
   115→            AcwrStatus::Caution
   116→        } else {
   117→            AcwrStatus::HighRisk
   118→        };
   119→
   120→        Acwr { ratio, status }
   121→    }
   122→
   123→    /// Check if we have enough data for meaningful ACWR (28+ days).
   124→    pub fn has_sufficient_history(&self, days: usize) -> bool {
   125→        days >= 28
   126→    }
   127→}
   128→
   129→impl Default for TrainingLoadCalculator {
   130→    fn default() -> Self {
   131→        Self::new()
   132→    }
   133→}
   134→
   135→impl Acwr {
   136→    /// Get color for UI display (RGB).
   137→    pub fn color(&self) -> (u8, u8, u8) {
   138→        match self.status {
   139→            AcwrStatus::Undertrained => (100, 149, 237), // Cornflower blue
   140→            AcwrStatus::Optimal => (50, 205, 50),        // Lime green
   141→            AcwrStatus::Caution => (255, 165, 0),        // Orange
   142→            AcwrStatus::HighRisk => (220, 20, 60),       // Crimson
   143→        }
   144→    }
   145→
   146→    /// Get recommendation text.
   147→    pub fn recommendation(&self) -> &'static str {
   148→        match self.status {
   149→            AcwrStatus::Undertrained => {
   150→                "Training load is low. Consider increasing training volume gradually."
   151→            }
   152→            AcwrStatus::Optimal => "Training load is in the optimal zone. Keep up the good work!",
   153→            AcwrStatus::Caution => {
   154→                "Training load is elevated. Monitor for signs of fatigue and consider recovery."
   155→            }
   156→            AcwrStatus::HighRisk => {
   157→                "Training load spike detected. High injury risk. Reduce training intensity."
   158→            }
   159→        }
   160→    }
   161→}
   162→
   163→impl DailyLoad {
   164→    /// Create a new DailyLoad with initial values.
   165→    pub fn new(tss: f32) -> Self {
   166→        Self {
   167→            tss,
   168→            atl: tss,
   169→            ctl: tss,
   170→            tsb: 0.0,
   171→        }
   172→    }
   173→}
   174→
   175→#[cfg(test)]
   176→mod tests {
   177→    use super::*;
   178→    use chrono::NaiveDate;
   179→
   180→    // T077: Unit test for EWMA ATL calculation (7-day)
   181→    #[test]
   182→    fn test_atl_calculation() {
   183→        let calc = TrainingLoadCalculator::new();
   184→
   185→        // Start with 0 load, add 100 TSS
   186→        let day1 = calc.calculate_day(DailyLoad::default(), 100.0);
   187→
   188→        // ATL should be 100 * (2/8) = 25
   189→        assert!((day1.atl - 25.0).abs() < 0.1);
   190→
   191→        // Add another 100 TSS
   192→        let day2 = calc.calculate_day(day1, 100.0);
   193→        // ATL should be 25 * 0.75 + 100 * 0.25 = 43.75
   194→        assert!((day2.atl - 43.75).abs() < 0.1);
   195→    }
   196→
   197→    // T078: Unit test for EWMA CTL calculation (42-day)
   198→    #[test]
   199→    fn test_ctl_calculation() {
   200→        let calc = TrainingLoadCalculator::new();
   201→
   202→        // Start with 0 load, add 100 TSS
   203→        let day1 = calc.calculate_day(DailyLoad::default(), 100.0);
   204→
   205→        // CTL k = 2/43 ≈ 0.0465
   206→        // CTL should be 100 * 0.0465 ≈ 4.65
   207→        assert!((day1.ctl - 4.65).abs() < 0.1);
   208→    }
   209→
   210→    // T079: Unit test for ACWR calculation and status thresholds
   211→    #[test]
   212→    fn test_acwr_thresholds() {
   213→        let calc = TrainingLoadCalculator::new();
   214→
   215→        // Undertrained: ACWR < 0.8
   216→        let under = calc.acwr(40.0, 100.0);
   217→        assert_eq!(under.status, AcwrStatus::Undertrained);
   218→        assert!((under.ratio - 0.4).abs() < 0.01);
   219→
   220→        // Optimal: 0.8 - 1.3
   221→        let optimal = calc.acwr(100.0, 100.0);
   222→        assert_eq!(optimal.status, AcwrStatus::Optimal);
   223→
   224→        // Caution: 1.3 - 1.5
   225→        let caution = calc.acwr(140.0, 100.0);
   226→        assert_eq!(caution.status, AcwrStatus::Caution);
   227→
   228→        // High risk: > 1.5
   229→        let high_risk = calc.acwr(200.0, 100.0);
   230→        assert_eq!(high_risk.status, AcwrStatus::HighRisk);
   231→    }
   232→
   233→    // T080: Unit test for cold start handling (no historical data)
   234→    #[test]
   235→    fn test_cold_start() {
   236→        let calc = TrainingLoadCalculator::new();
   237→
   238→        // Empty history
   239→        let history = calc.calculate_history(&[]);
   240→        assert!(history.is_empty());
   241→
   242→        // First day with TSS
   243→        let daily_tss = vec![(NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), 100.0)];
   244→        let history = calc.calculate_history(&daily_tss);
   245→
   246→        assert_eq!(history.len(), 1);
   247→        assert!(history[0].1.atl > 0.0);
   248→        assert!(history[0].1.ctl > 0.0);
   249→
   250→        // Check insufficient history flag
   251→        assert!(!calc.has_sufficient_history(1));
   252→        assert!(calc.has_sufficient_history(28));
   253→    }
   254→
   255→    #[test]
   256→    fn test_tsb_calculation() {
   257→        let calc = TrainingLoadCalculator::new();
   258→
   259→        // Build up load over several days
   260→        let mut prev = DailyLoad::default();
   261→        for _ in 0..30 {
   262→            prev = calc.calculate_day(prev, 100.0);
   263→        }
   264→
   265→        // TSB should be CTL - ATL
   266→        assert!((prev.tsb - (prev.ctl - prev.atl)).abs() < 0.01);
   267→    }
   268→
