     1→//! VO2max Estimation from power data.
     2→//!
     3→//! Estimates VO2max without physiological testing using:
     4→//! - Hawley-Noakes formula based on power:weight ratio
     5→//! - Correlation with Critical Power and FTP
     6→
     7→use serde::{Deserialize, Serialize};
     8→
     9→/// VO2max estimation result.
    10→#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
    11→pub struct Vo2maxResult {
    12→    /// Estimated VO2max in ml/kg/min.
    13→    pub vo2max: f32,
    14→    /// Fitness classification.
    15→    pub classification: FitnessLevel,
    16→    /// Estimation method used.
    17→    pub method: Vo2maxMethod,
    18→}
    19→
    20→/// Fitness classification based on VO2max.
    21→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    22→pub enum FitnessLevel {
    23→    /// VO2max < 35: Untrained.
    24→    Untrained,
    25→    /// VO2max 35-45: Recreational.
    26→    Recreational,
    27→    /// VO2max 45-55: Trained.
    28→    Trained,
    29→    /// VO2max 55-65: Well-trained.
    30→    WellTrained,
    31→    /// VO2max 65-75: Elite.
    32→    Elite,
    33→    /// VO2max > 75: World-class.
    34→    WorldClass,
    35→}
    36→
    37→/// Method used for VO2max estimation.
    38→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    39→pub enum Vo2maxMethod {
    40→    /// Based on 5-minute max power (Hawley-Noakes).
    41→    FiveMinutePower,
    42→    /// Based on FTP and body weight.
    43→    FtpBased,
    44→    /// Based on Critical Power.
    45→    CriticalPowerBased,
    46→}
