    12→/// A single point on the power duration curve.
    13→#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
    14→pub struct PdcPoint {
    15→    /// Duration in seconds.
    16→    pub duration_secs: u32,
    17→    /// Maximum average power at this duration (watts).
    18→    pub power_watts: u16,
    19→}
    20→
    21→/// Power Duration Curve - collection of max power values at each duration.
    22→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
    23→pub struct PowerDurationCurve {
    24→    /// PDC points, sorted by duration.
    25→    points: Vec<PdcPoint>,
    26→}
    27→
    28→impl PowerDurationCurve {
    29→    /// Create an empty PDC.
    30→    pub fn new() -> Self {
    31→        Self { points: Vec::new() }
    32→    }
    33→
    34→    /// Create PDC from existing points.
    35→    pub fn from_points(mut points: Vec<PdcPoint>) -> Self {
    36→        points.sort_by_key(|p| p.duration_secs);
    37→        Self { points }
    38→    }
    39→
    40→    /// Get power at a specific duration (interpolates if needed).
    41→    pub fn power_at(&self, duration_secs: u32) -> Option<u16> {
    42→        if self.points.is_empty() {
    43→            return None;
    44→        }
    45→
    46→        // Exact match
    47→        if let Some(point) = self
    48→            .points
    49→            .iter()
    50→            .find(|p| p.duration_secs == duration_secs)
    51→        {
    52→            return Some(point.power_watts);
    53→        }
    54→
    55→        // Find surrounding points for interpolation
    56→        let mut lower: Option<&PdcPoint> = None;
    57→        let mut upper: Option<&PdcPoint> = None;
    58→
    59→        for point in &self.points {
    60→            if point.duration_secs < duration_secs {
    61→                lower = Some(point);
    62→            } else if point.duration_secs > duration_secs {
    63→                upper = Some(point);
    64→                break;
    65→            }
    66→        }
    67→
    68→        match (lower, upper) {
    69→            (Some(l), Some(u)) => {
    70→                // Linear interpolation
    71→                let ratio = (duration_secs - l.duration_secs) as f32
    72→                    / (u.duration_secs - l.duration_secs) as f32;
    73→                let power =
    74→                    l.power_watts as f32 + ratio * (u.power_watts as f32 - l.power_watts as f32);
    75→                Some(power.round() as u16)
    76→            }
    77→            (Some(l), None) => Some(l.power_watts), // Beyond max duration
    78→            (None, Some(u)) => Some(u.power_watts), // Below min duration
    79→            (None, None) => None,
    80→        }
    81→    }
    82→
    83→    /// Get all points for charting.
    84→    pub fn points(&self) -> &[PdcPoint] {
    85→        &self.points
    86→    }
    87→
    88→    /// Update PDC with new ride data, returns which points changed.
    89→    pub fn update(&mut self, new_points: &[PdcPoint]) -> Vec<PdcPoint> {
    90→        let mut changed = Vec::new();
    91→
    92→        for new_point in new_points {
    93→            if let Some(existing) = self
    94→                .points
    95→                .iter_mut()
    96→                .find(|p| p.duration_secs == new_point.duration_secs)
    97→            {
    98→                if new_point.power_watts > existing.power_watts {
    99→                    *existing = *new_point;
   100→                    changed.push(*new_point);
   101→                }
   102→            } else {
   103→                self.points.push(*new_point);
   104→                changed.push(*new_point);
   105→            }
   106→        }
   107→
   108→        self.points.sort_by_key(|p| p.duration_secs);
   109→        changed
   110→    }
