   112→    /// Check if sufficient data exists for CP calculation (3+ points in 2-20 min range).
   113→    pub fn has_sufficient_data_for_cp(&self) -> bool {
   114→        let cp_range_points = self
   115→            .points
   116→            .iter()
   117→            .filter(|p| p.duration_secs >= 120 && p.duration_secs <= 1200)
   118→            .count();
   119→        cp_range_points >= 3
   120→    }
