   135→        self.points.len()
   136→    }
   137→
   138→    /// Check if there's actual data at or near a duration (not extrapolated).
   139→    /// Returns true if there's a point within tolerance of the target duration.
   140→    pub fn has_data_near(&self, duration_secs: u32, tolerance_secs: u32) -> bool {
   141→        self.points
   142→            .iter()
   143→            .any(|p| p.duration_secs.abs_diff(duration_secs) <= tolerance_secs)
   144→    }
   145→
   146→    /// Get power only if there's actual data at or near this duration.
   147→    /// Uses tolerance to avoid relying on extrapolated values.
   148→    pub fn power_at_actual(&self, duration_secs: u32, tolerance_secs: u32) -> Option<u16> {
   149→        if self.has_data_near(duration_secs, tolerance_secs) {
