     1→//! Training Load calculations (ATL/CTL/ACWR).
     2→//!
     3→//! Implements the Performance Management Chart (PMC) model:
     4→//! - ATL (Acute Training Load): 7-day exponentially weighted moving average
     5→//! - CTL (Chronic Training Load): 42-day exponentially weighted moving average
     6→//! - TSB (Training Stress Balance): CTL - ATL
     7→//! - ACWR (Acute:Chronic Workload Ratio): ATL / CTL
     8→
     9→use chrono::NaiveDate;
    10→use serde::{Deserialize, Serialize};
    11→
    12→/// Daily training load values.
    13→#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize)]
    14→pub struct DailyLoad {
    15→    /// Total TSS for the day.
    16→    pub tss: f32,
    17→    /// Acute Training Load (7-day EWMA).
    18→    pub atl: f32,
    19→    /// Chronic Training Load (42-day EWMA).
    20→    pub ctl: f32,
    21→    /// Training Stress Balance (CTL - ATL).
    22→    pub tsb: f32,
    23→}
    24→
    25→/// ACWR status thresholds.
    26→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    27→pub enum AcwrStatus {
    28→    /// ACWR < 0.8: Undertrained (detraining risk).
    29→    Undertrained,
    30→    /// ACWR 0.8 - 1.3: Optimal training zone.
    31→    Optimal,
    32→    /// ACWR 1.3 - 1.5: Caution zone.
    33→    Caution,
    34→    /// ACWR > 1.5: High injury risk.
    35→    HighRisk,
    36→}
    37→
    38→/// Acute:Chronic Workload Ratio result.
    39→#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
    40→pub struct Acwr {
    41→    /// The ratio value.
    42→    pub ratio: f32,
    43→    /// Status classification.
    44→    pub status: AcwrStatus,
    45→}
    46→
    47→/// Training load calculator.
    48→pub struct TrainingLoadCalculator {
    49→    /// ATL decay constant (default: 7 days).
    50→    atl_days: f32,
    51→    /// CTL decay constant (default: 42 days).
    52→    ctl_days: f32,
    53→}
    54→
    55→impl TrainingLoadCalculator {
    56→    /// Create with default constants (7/42 day).
    57→    pub fn new() -> Self {
    58→        Self {
    59→            atl_days: 7.0,
    60→            ctl_days: 42.0,
    61→        }
    62→    }
    63→
    64→    /// Create with custom decay constants.
    65→    pub fn with_constants(atl_days: f32, ctl_days: f32) -> Self {
    66→        Self { atl_days, ctl_days }
    67→    }
    68→
    69→    /// Calculate training load for a date given previous day's values and today's TSS.
    70→    pub fn calculate_day(&self, prev: DailyLoad, today_tss: f32) -> DailyLoad {
    71→        // EWMA formula: new = old × (1 - k) + value × k
    72→        // where k = 2 / (N + 1)
    73→        let atl_k = 2.0 / (self.atl_days + 1.0);
    74→        let ctl_k = 2.0 / (self.ctl_days + 1.0);
    75→
    76→        let new_atl = prev.atl * (1.0 - atl_k) + today_tss * atl_k;
    77→        let new_ctl = prev.ctl * (1.0 - ctl_k) + today_tss * ctl_k;
    78→        let new_tsb = new_ctl - new_atl;
    79→
    80→        DailyLoad {
    81→            tss: today_tss,
    82→            atl: new_atl,
    83→            ctl: new_ctl,
    84→            tsb: new_tsb,
    85→        }
    86→    }
    87→
    88→    /// Calculate full history from daily TSS values.
    89→    pub fn calculate_history(&self, daily_tss: &[(NaiveDate, f32)]) -> Vec<(NaiveDate, DailyLoad)> {
    90→        if daily_tss.is_empty() {
    91→            return Vec::new();
    92→        }
    93→
    94→        let mut results = Vec::with_capacity(daily_tss.len());
    95→        let mut prev = DailyLoad::default();
    96→
    97→        for (date, tss) in daily_tss {
    98→            let load = self.calculate_day(prev, *tss);
    99→            results.push((*date, load));
   100→            prev = load;
   101→        }
   102→
   103→        results
   104→    }
   105→
   106→    /// Calculate ACWR from current ATL/CTL.
   107→    pub fn acwr(&self, atl: f32, ctl: f32) -> Acwr {
   108→        let ratio = if ctl > 0.0 { atl / ctl } else { 0.0 };
   109→
   110→        let status = if ratio < 0.8 {
   111→            AcwrStatus::Undertrained
   112→        } else if ratio <= 1.3 {
   113→            AcwrStatus::Optimal
   114→        } else if ratio <= 1.5 {
   115→            AcwrStatus::Caution
   116→        } else {
   117→            AcwrStatus::HighRisk
   118→        };
   119→
   120→        Acwr { ratio, status }
   121→    }
   122→
   123→    /// Check if we have enough data for meaningful ACWR (28+ days).
   124→    pub fn has_sufficient_history(&self, days: usize) -> bool {
   125→        days >= 28
   126→    }
   127→}
