    90→/// Includes date, TSS, and all calculated load metrics.
    91→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
    92→pub struct DailyLoadExport {
    93→    /// The date for this training load entry.
    94→    pub date: NaiveDate,
    95→    /// Training Stress Score for the day.
    96→    pub tss: f32,
