    98→    pub atl: f32,
    99→    /// Chronic Training Load (42-day EWMA).
   100→    pub ctl: f32,
   101→    /// Training Stress Balance (CTL - ATL).
   102→    pub tsb: f32,
   103→    /// Acute:Chronic Workload Ratio (ATL / CTL), if calculable.
   104→    #[serde(skip_serializing_if = "Option::is_none")]
   105→    pub acwr: Option<f32>,
   106→}
