   108→impl DailyLoadExport {
   109→    /// Create a new daily load export entry.
   110→    pub fn new(date: NaiveDate, tss: f32, atl: f32, ctl: f32, tsb: f32) -> Self {
   111→        Self {
   112→            date,
   113→            tss,
   114→            atl,
   115→            ctl,
   116→            tsb,
   117→            acwr: None,
   118→        }
   119→    }
   120→
   121→    /// Create a new daily load export entry with ACWR.
   122→    pub fn with_acwr(date: NaiveDate, tss: f32, atl: f32, ctl: f32, tsb: f32, acwr: f32) -> Self {
   123→        Self {
   124→            date,
   125→            tss,
   126→            atl,
   127→            ctl,
   128→            tsb,
   129→            acwr: Some(acwr),
   130→        }
   131→    }
