    26→/// Model fitting errors.
    27→#[derive(Debug, Error)]
    28→pub enum CpFitError {
    29→    /// Insufficient data points for fitting.
    30→    #[error("Insufficient data points (need at least 3, got {0})")]
    31→    InsufficientData(usize),
    32→
    33→    /// Invalid duration range in data.
    34→    #[error("Invalid duration range (need 2-20 minute efforts)")]
    35→    InvalidDurationRange,
