    42→/// CP model fitter.
    43→pub struct CpFitter {
    44→    /// Minimum duration for fitting (default: 120s / 2 min).
    45→    min_duration: u32,
    46→    /// Maximum duration for fitting (default: 1200s / 20 min).
    47→    max_duration: u32,
    48→}
    49→
    50→impl CpFitter {
    51→    /// Create with default settings (2-20 min range).
    52→    pub fn new() -> Self {
    53→        Self {
    54→            min_duration: 120,
    55→            max_duration: 1200,
    56→        }
    57→    }
    58→
    59→    /// Create with custom duration range.
    60→    pub fn with_range(min_secs: u32, max_secs: u32) -> Self {
    61→        Self {
    62→            min_duration: min_secs,
    63→            max_duration: max_secs,
    64→        }
    65→    }
    66→
    67→    /// Fit CP model from PDC points.
    68→    pub fn fit(&self, pdc: &PowerDurationCurve) -> Result<CpModel, CpFitError> {
    69→        let points: Vec<(u32, u16)> = pdc
    70→            .points()
    71→            .iter()
    72→            .filter(|p| {
    73→                p.duration_secs >= self.min_duration && p.duration_secs <= self.max_duration
    74→            })
    75→            .map(|p| (p.duration_secs, p.power_watts))
    76→            .collect();
    77→
    78→        self.fit_points(&points)
    79→    }
    80→
    81→    /// Fit from explicit (duration, power) pairs.
    82→    pub fn fit_points(&self, points: &[(u32, u16)]) -> Result<CpModel, CpFitError> {
    83→        if points.len() < 3 {
    84→            return Err(CpFitError::InsufficientData(points.len()));
    85→        }
    86→
    87→        // Validate duration range
    88→        let has_valid_range = points
    89→            .iter()
    90→            .any(|(d, _)| *d >= self.min_duration && *d <= self.max_duration);
    91→        if !has_valid_range {
    92→            return Err(CpFitError::InvalidDurationRange);
    93→        }
    94→
    95→        // Transform to linear form: Work = CP × time + W'
    96→        // where work = power × duration
    97→        let work_time_pairs: Vec<(f64, f64)> = points
    98→            .iter()
    99→            .map(|(d, p)| (*d as f64, *p as f64 * *d as f64))
   100→            .collect();
   101→
   102→        // Linear regression: work = slope * time + intercept
   103→        // slope = CP, intercept = W'
   104→        let (slope, intercept, r_squared) = linear_regression(&work_time_pairs)?;
   105→
   106→        // Validate results
   107→        if slope <= 0.0 || intercept <= 0.0 {
   108→            return Err(CpFitError::FittingFailed(
   109→                "Invalid CP/W' values (must be positive)".to_string(),
   110→            ));
   111→        }
   112→
   113→        Ok(CpModel {
   114→            cp: slope.round() as u16,
   115→            w_prime: intercept.round() as u32,
   116→            r_squared: r_squared as f32,
   117→        })
   118→    }
   119→}
