   127→impl CpModel {
   128→    /// Predict time to exhaustion at given power.
   129→    /// Returns None if power <= CP (theoretically infinite).
   130→    pub fn time_to_exhaustion(&self, power_watts: u16) -> Option<Duration> {
   131→        if power_watts <= self.cp {
   132→            return None; // Infinite (sustainable)
   133→        }
   134→
   135→        let tte_secs = self.w_prime as f64 / (power_watts as f64 - self.cp as f64);
   136→        Some(Duration::from_secs_f64(tte_secs))
   137→    }
   138→
   139→    /// Predict sustainable power for given duration.
   140→    pub fn power_at_duration(&self, duration: Duration) -> u16 {
   141→        let secs = duration.as_secs_f64();
   142→        if secs <= 0.0 {
   143→            return 0;
   144→        }
   145→
   146→        let power = self.cp as f64 + self.w_prime as f64 / secs;
   147→        power.round() as u16
   148→    }
   149→
   150→    /// Calculate remaining W' after work at given power/duration.
   151→    /// Returns negative if W' would be depleted.
   152→    pub fn w_prime_remaining(&self, power_watts: u16, duration: Duration) -> i32 {
   153→        if power_watts <= self.cp {
   154→            return self.w_prime as i32; // No W' depletion below CP
   155→        }
   156→
   157→        let work_above_cp = (power_watts as f64 - self.cp as f64) * duration.as_secs_f64();
   158→        self.w_prime as i32 - work_above_cp.round() as i32
   159→    }
   160→}
   161→
   162→/// Linear regression on (x, y) pairs.
   163→/// Returns (slope, intercept, r_squared).
   164→fn linear_regression(points: &[(f64, f64)]) -> Result<(f64, f64, f64), CpFitError> {
   165→    let n = points.len() as f64;
   166→    if n < 2.0 {
   167→        return Err(CpFitError::FittingFailed(
   168→            "Need at least 2 points for regression".to_string(),
   169→        ));
   170→    }
   171→
   172→    let sum_x: f64 = points.iter().map(|(x, _)| x).sum();
   173→    let sum_y: f64 = points.iter().map(|(_, y)| y).sum();
   174→    let sum_xy: f64 = points.iter().map(|(x, y)| x * y).sum();
   175→    let sum_xx: f64 = points.iter().map(|(x, _)| x * x).sum();
   176→    let _sum_yy: f64 = points.iter().map(|(_, y)| y * y).sum();
   177→
   178→    let denom = n * sum_xx - sum_x * sum_x;
   179→    if denom.abs() < 1e-10 {
   180→        return Err(CpFitError::FittingFailed(
   181→            "Singular matrix in regression".to_string(),
   182→        ));
   183→    }
   184→
   185→    let slope = (n * sum_xy - sum_x * sum_y) / denom;
   186→    let intercept = (sum_y - slope * sum_x) / n;
   187→
   188→    // Calculate R²
   189→    let mean_y = sum_y / n;
   190→    let ss_tot: f64 = points.iter().map(|(_, y)| (y - mean_y).powi(2)).sum();
   191→    let ss_res: f64 = points
   192→        .iter()
   193→        .map(|(x, y)| {
   194→            let predicted = slope * x + intercept;
   195→            (y - predicted).powi(2)
   196→        })
   197→        .sum();
   198→
   199→    let r_squared = if ss_tot > 0.0 {
   200→        1.0 - ss_res / ss_tot
   201→    } else {
   202→        0.0
   203→    };
   204→
   205→    Ok((slope, intercept, r_squared))
   206→}
