     1→//! VO2max Estimation from power data.
     2→//!
     3→//! Estimates VO2max without physiological testing using:
     4→//! - Hawley-Noakes formula based on power:weight ratio
     5→//! - Correlation with Critical Power and FTP
     6→
     7→use serde::{Deserialize, Serialize};
     8→
     9→/// VO2max estimation result.
    10→#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
    11→pub struct Vo2maxResult {
    12→    /// Estimated VO2max in ml/kg/min.
    13→    pub vo2max: f32,
    14→    /// Fitness classification.
    15→    pub classification: FitnessLevel,
    16→    /// Estimation method used.
    17→    pub method: Vo2maxMethod,
    18→}
    19→
    20→/// Fitness classification based on VO2max.
    21→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    22→pub enum FitnessLevel {
    23→    /// VO2max < 35: Untrained.
    24→    Untrained,
    25→    /// VO2max 35-45: Recreational.
    26→    Recreational,
    27→    /// VO2max 45-55: Trained.
    28→    Trained,
    29→    /// VO2max 55-65: Well-trained.
    30→    WellTrained,
    31→    /// VO2max 65-75: Elite.
    32→    Elite,
    33→    /// VO2max > 75: World-class.
    34→    WorldClass,
    35→}
    36→
    37→/// Method used for VO2max estimation.
    38→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    39→pub enum Vo2maxMethod {
    40→    /// Based on 5-minute max power (Hawley-Noakes).
    41→    FiveMinutePower,
    42→    /// Based on FTP and body weight.
    43→    FtpBased,
    44→    /// Based on Critical Power.
    45→    CriticalPowerBased,
    46→}
    47→
    48→/// VO2max calculator.
    49→pub struct Vo2maxCalculator {
    50→    /// Athlete body weight in kg.
    51→    weight_kg: f32,
    52→}
    53→
    54→impl Vo2maxCalculator {
    55→    /// Create a new calculator with athlete weight.
    56→    pub fn new(weight_kg: f32) -> Self {
    57→        Self { weight_kg }
    58→    }
    59→
    60→    /// Estimate VO2max from 5-minute max power using Hawley-Noakes formula.
    61→    /// Formula: VO2max = (10.8 × P5min / weight) + 7
    62→    pub fn from_five_minute_power(&self, power_5min: u16) -> Vo2maxResult {
    63→        let power_per_kg = power_5min as f32 / self.weight_kg;
    64→        let vo2max = 10.8 * power_per_kg + 7.0;
    65→
    66→        Vo2maxResult {
    67→            vo2max,
    68→            classification: Self::classify(vo2max),
    69→            method: Vo2maxMethod::FiveMinutePower,
    70→        }
    71→    }
    72→
    73→    /// Estimate VO2max from FTP.
    74→    /// Uses empirical correlation: VO2max ≈ FTP/weight × 12 + 3.5
    75→    pub fn from_ftp(&self, ftp: u16) -> Vo2maxResult {
    76→        let ftp_per_kg = ftp as f32 / self.weight_kg;
    77→        let vo2max = ftp_per_kg * 12.0 + 3.5;
    78→
    79→        Vo2maxResult {
    80→            vo2max,
    81→            classification: Self::classify(vo2max),
    82→            method: Vo2maxMethod::FtpBased,
    83→        }
    84→    }
    85→
    86→    /// Estimate VO2max from Critical Power.
    87→    /// CP correlates closely with VO2max: VO2max ≈ CP/weight × 12.5 + 2
    88→    pub fn from_critical_power(&self, cp: u16) -> Vo2maxResult {
    89→        let cp_per_kg = cp as f32 / self.weight_kg;
    90→        let vo2max = cp_per_kg * 12.5 + 2.0;
    91→
    92→        Vo2maxResult {
    93→            vo2max,
    94→            classification: Self::classify(vo2max),
    95→            method: Vo2maxMethod::CriticalPowerBased,
    96→        }
    97→    }
    98→
    99→    /// Classify fitness level based on VO2max.
   100→    fn classify(vo2max: f32) -> FitnessLevel {
   101→        if vo2max < 35.0 {
   102→            FitnessLevel::Untrained
   103→        } else if vo2max < 45.0 {
   104→            FitnessLevel::Recreational
   105→        } else if vo2max < 55.0 {
   106→            FitnessLevel::Trained
   107→        } else if vo2max < 65.0 {
   108→            FitnessLevel::WellTrained
   109→        } else if vo2max < 75.0 {
   110→            FitnessLevel::Elite
   111→        } else {
   112→            FitnessLevel::WorldClass
   113→        }
   114→    }
   115→}
