   119→    pub fn description(&self) -> &'static str {
   120→        match self {
   121→            FitnessLevel::Untrained => "Untrained - Consider starting with easy endurance rides",
   122→            FitnessLevel::Recreational => "Recreational - Good base fitness for cycling",
   123→            FitnessLevel::Trained => "Trained - Solid aerobic capacity",
   124→            FitnessLevel::WellTrained => "Well-trained - Competitive amateur level",
   125→            FitnessLevel::Elite => "Elite - Professional or high-level amateur",
   126→            FitnessLevel::WorldClass => "World-class - Top-tier athletic capacity",
   127→        }
   128→    }
   129→}
