   138→        let calc = Vo2maxCalculator::new(70.0);
   139→
   140→        // 5-min power of 350W for 70kg rider
   141→        // VO2max = 10.8 × (350/70) + 7 = 10.8 × 5 + 7 = 61
   142→        let result = calc.from_five_minute_power(350);
   143→        assert!((result.vo2max - 61.0).abs() < 0.5);
