    70→impl LeaderboardExporter {
    71→    /// Create a new exporter.
    72→    pub fn new(db: Arc<Database>) -> Self {
    73→        Self { db }
    74→    }
    75→
    76→    /// Export leaderboard to JSON.
    77→    pub fn export_json(&self, segment_id: Uuid) -> Result<String, ExportError> {
    78→        let export = self.build_export(segment_id)?;
    79→        serde_json::to_string_pretty(&export)
    80→            .map_err(|e| ExportError::SerializationFailed(e.to_string()))
    81→    }
    82→
    83→    /// Export leaderboard to CSV.
    84→    pub fn export_csv(&self, segment_id: Uuid) -> Result<String, ExportError> {
    85→        let export = self.build_export(segment_id)?;
    86→
    87→        let mut csv = String::new();
    88→        csv.push_str("rank,rider_name,elapsed_time_ms,avg_power_watts,recorded_at\n");
    89→
    90→        for effort in &export.efforts {
    91→            csv.push_str(&format!(
    92→                "{},{},{},{},{}\n",
    93→                effort.rank,
    94→                escape_csv(&effort.rider_name),
    95→                effort.elapsed_time_ms,
    96→                effort
    97→                    .avg_power_watts
    98→                    .map_or(String::new(), |p| p.to_string()),
    99→                effort.recorded_at.to_rfc3339(),
   100→            ));
   101→        }
   102→
   103→        Ok(csv)
   104→    }
   105→
   106→    /// Import efforts from JSON.
   107→    pub fn import_json(&self, json_content: &str) -> Result<ImportResult, ExportError> {
   108→        let export: LeaderboardExport = serde_json::from_str(json_content)
   109→            .map_err(|e| ExportError::ParseError(e.to_string()))?;
   110→
   111→        let conn = self.db.connection();
   112→
   113→        // Find or create segment
   114→        let segment_id = self.find_or_create_segment(&export.segment)?;
   115→
   116→        let mut imported_count = 0u32;
   117→        let mut duplicate_count = 0u32;
   118→        let mut name_conflicts = Vec::new();
   119→
   120→        // Group efforts by rider name
   121→        let mut efforts_by_name: std::collections::HashMap<String, Vec<&EffortExport>> =
   122→            std::collections::HashMap::new();
   123→        for effort in &export.efforts {
   124→            efforts_by_name
   125→                .entry(effort.rider_name.clone())
   126→                .or_default()
   127→                .push(effort);
   128→        }
   129→
   130→        // Process each rider
   131→        for (rider_name, efforts) in efforts_by_name {
   132→            // Check for existing rider with same name
   133→            let existing_rider_id = self.find_rider_by_name(&rider_name)?;
   134→
   135→            if let Some(rider_id) = existing_rider_id {
   136→                // Check if this is a name conflict (might be different person)
