    95→    /// Export the PDC data to CSV format.
    96→    ///
    97→    /// Returns a CSV string with headers: `duration_secs,power_watts,achieved_at`
    98→    ///
    99→    /// The `achieved_at` column contains ISO 8601 timestamps when available,
   100→    /// or is empty when the timestamp is not tracked.
   101→    ///
   102→    /// # Example
   103→    ///
   104→    /// ```ignore
   105→    /// let pdc = PdcExport::from_points(vec![
   106→    ///     PdcPointExport::new(60, 350),
   107→    ///     PdcPointExport::new(300, 280),
   108→    /// ]);
   109→    /// let csv = pdc.to_csv();
   110→    /// // csv contains:
   111→    /// // duration_secs,power_watts,achieved_at
   112→    /// // 60,350,
   113→    /// // 300,280,
   114→    /// ```
   115→    pub fn to_csv(&self) -> String {
   116→        let mut csv = String::new();
   117→        csv.push_str("duration_secs,power_watts,achieved_at\n");
   118→
   119→        for point in &self.points {
